insert into jewelry_categories (slug, name_de, name_en, description_de, description_en, kind, sort_order) values
  ('trauringe', 'Trauringe', 'Wedding rings', 'Schlichte und gewölbte Bänder für Paare. Jedes Stück wird nach Größe und Legierung angefragt, nicht aus einem Preisschild verkauft.', 'Plain and domed bands for couples. Each piece is requested by size and alloy, never sold from a price tag.', 'ring', 1),
  ('verlobungsringe', 'Verlobungsringe', 'Engagement rings', 'Solitäre und zarte Pavé-Bänder. Der Stein wird im Angebot beschrieben — auf dieser Seite steht kein Preis.', 'Solitaires and fine pavé bands. The stone is described in the offer — this page shows no price.', 'ring', 2),
  ('weitere-ringe', 'Weitere Ringe', 'Other rings', 'Siegelringe, Stapelringe und breitere Bänder für den Alltag.', 'Signet rings, stacking rings and wider everyday bands.', 'ring', 3),
  ('ketten', 'Ketten', 'Chains', 'Glieder- und Kugelketten in Gold und Silber, Länge und Verschluss nach Absprache.', 'Trace and bead chains in gold and silver, length and clasp agreed with the offer.', 'jewelry', 4),
  ('ohrringe', 'Ohrringe', 'Earrings', 'Creolen und Stecker, leicht genug für den Tag, gefertigt nach Anfrage.', 'Hoops and studs, light enough for the day, made after a request.', 'jewelry', 5),
  ('anhaenger', 'Anhänger', 'Pendants', 'Tropfen und Medaillons, die an einer Fatlum-Kette oder an Ihrer eigenen Kette getragen werden.', 'Drops and lockets, worn on a Fatlum chain or on a chain you already own.', 'jewelry', 6)
insert into jewelry_products (slug, sku, category_slug, name_de, name_en, description_de, description_en, metal_group, metal_de, metal_en, alloy_de, alloy_en, width_mm, size_min, size_max, lead_de, lead_en, glyph, tone, sort_order) values
  ('aurelia', 'FJ-TR-001', 'trauringe', 'Aurelia', 'Aurelia', 'Gerade Planlinie in Gelbgold 585, vier Millimeter breit. Die Fläche nimmt eine Innengravur auf und bleibt ruhig neben einem schmaleren Verlobungsring. Größen 48 bis 70, gefertigt nach Anfrage.', 'A straight flat band in 585 yellow gold, four millimetres wide. The face takes an inside engraving and sits quietly next to a narrower engagement ring. Sizes 48 to 70, made to request.', 'gold', 'Gelbgold', 'Yellow gold', '585 Gelbgold', '585 yellow gold', 4, 48, 70, 'Den Termin nennen wir im Angebot, üblicherweise einige Wochen nach Freigabe.', 'We name the date in the offer, usually a few weeks after you approve it.', 'band', 'yellow', 1),
  ('nordlicht', 'FJ-TR-002', 'trauringe', 'Nordlicht', 'Nordlicht', 'Hofband in Weißgold 585 mit leichter Außenwölbung. Drei Millimeter, damit es unter einem Solitär nicht drängt. Die Farbe bleibt kühl, ohne dass wir eine Rhodiumschicht versprechen — das klären wir im Angebot.', 'A court band in 585 white gold with a light outer curve. Three millimetres, so it does not crowd a solitaire. The colour stays cool; we do not promise a rhodium plate — that is settled in the offer.', 'gold', 'Weißgold', 'White gold', '585 Weißgold', '585 white gold', 3, 48, 70, 'Den Termin nennen wir im Angebot, üblicherweise einige Wochen nach Freigabe.', 'We name the date in the offer, usually a few weeks after you approve it.', 'band', 'white', 2),
  ('rosa', 'FJ-TR-003', 'trauringe', 'Rosa', 'Rosa', 'Komfortprofil in Roségold 585. Der runde Querschnitt liegt weich am Finger, die Breite von 4,5 Millimetern trägt eine kurze Innengravur. Für Paare, die beide Ringe gleich und nur die Größe verschieden wollen.', 'A comfort profile in 585 rose gold. The round section sits softly on the finger, and 4.5 millimetres of width carries a short inside engraving. For couples who want both rings alike and only the sizes different.', 'gold', 'Roségold', 'Rose gold', '585 Roségold', '585 rose gold', 4.5, 48, 70, 'Den Termin nennen wir im Angebot, üblicherweise einige Wochen nach Freigabe.', 'We name the date in the offer, usually a few weeks after you approve it.', 'band', 'rose', 3),
  ('alba', 'FJ-TR-004', 'trauringe', 'Alba', 'Alba', 'Schmale Hofband aus Platin 950. Das Metall ist dicht und hell und wird im Alltag weniger warm als Weißgold. Breite 2,5 Millimeter, Größen 48 bis 68.', 'A narrow court band in 950 platinum. The metal is dense and bright, and it stays less warm in daily wear than white gold. Width 2.5 millimetres, sizes 48 to 68.', 'platinum', 'Platin', 'Platinum', 'Platin 950', 'Platinum 950', 2.5, 48, 68, 'Platin braucht etwas länger in der Werkstatt. Den Termin nennen wir im Angebot.', 'Platinum needs a little longer in the workshop. We name the date in the offer.', 'band', 'platinum', 4),
  ('cora', 'FJ-TR-005', 'trauringe', 'Cora', 'Cora', 'Doppelbogen in Rotgold 750. Außen und innen gewölbt, fünf Millimeter breit, mit einer klaren roten Farbe. Für Paare, die ein kräftigeres Band suchen.', 'A double curve in 750 red gold. Domed outside and in, five millimetres wide, with a clear red colour. For couples who want a stronger band.', 'gold', 'Rotgold', 'Red gold', '750 Rotgold', '750 red gold', 5, 50, 70, 'Den Termin nennen wir im Angebot, üblicherweise einige Wochen nach Freigabe.', 'We name the date in the offer, usually a few weeks after you approve it.', 'band', 'red', 5),
  ('solis', 'FJ-VL-001', 'verlobungsringe', 'Solis', 'Solis', 'Solitär auf einem schmalen Gelbgoldband 750. Die Fassung und die Steinbeschreibung stehen im Angebot, nicht auf dieser Seite. Lose Steine führen wir bei Fatlum Diamonds.', 'A solitaire on a narrow 750 yellow-gold band. The setting and the stone description live in the offer, not on this page. Loose stones are with Fatlum Diamonds.', 'gold', 'Gelbgold', 'Yellow gold', '750 Gelbgold', '750 yellow gold', 1.8, 48, 66, 'Hängt vom Stein ab. Den Termin nennen wir, sobald Fassung und Stein feststehen.', 'Depends on the stone. We name the date once setting and stone are fixed.', 'solitaire', 'yellow', 6),
  ('vespera', 'FJ-VL-002', 'verlobungsringe', 'Vespera', 'Vespera', 'Solitär in Roségold 750 mit einer niedrigen Fassung, die am Trauring nicht hakt. Das Band ist zwei Millimeter breit.', 'A solitaire in 750 rose gold with a low setting that does not catch on a wedding band. The shank is two millimetres wide.', 'gold', 'Roségold', 'Rose gold', '750 Roségold', '750 rose gold', 2, 48, 66, 'Hängt vom Stein ab. Den Termin nennen wir, sobald Fassung und Stein feststehen.', 'Depends on the stone. We name the date once setting and stone are fixed.', 'solitaire', 'rose', 7),
  ('klarheit', 'FJ-VL-003', 'verlobungsringe', 'Klarheit', 'Klarheit', 'Solitär in Weißgold 750. Vier Krappen, schmales Band, ruhige Linie. Welche Legierung nickelarm gefertigt wird, bestätigen wir im Angebot — bitte Allergien in die Nachricht schreiben.', 'A solitaire in 750 white gold. Four claws, a narrow shank, a quiet line. Which alloy is made low-nickel is confirmed in the offer — please mention allergies in the message.', 'gold', 'Weißgold', 'White gold', '750 Weißgold', '750 white gold', 1.8, 48, 66, 'Hängt vom Stein ab. Den Termin nennen wir, sobald Fassung und Stein feststehen.', 'Depends on the stone. We name the date once setting and stone are fixed.', 'solitaire', 'white', 8),
  ('mira', 'FJ-VL-004', 'verlobungsringe', 'Mira', 'Mira', 'Pavé-Band in Weißgold 585. Kleine Steine sitzen über die halbe Sichtfläche, das Band bleibt bei 2,2 Millimetern tragbar. Anzahl und Größe der Steine stehen im Angebot.', 'A pavé band in 585 white gold. Small stones sit across the upper half, and the band stays wearable at 2.2 millimetres. Count and size of the stones are in the offer.', 'gold', 'Weißgold', 'White gold', '585 Weißgold', '585 white gold', 2.2, 48, 66, 'Hängt von der Steinanzahl ab. Den Termin nennen wir im Angebot.', 'Depends on the stone count. We name the date in the offer.', 'pave', 'white', 9),
  ('forum', 'FJ-WR-001', 'weitere-ringe', 'Forum', 'Forum', 'Siegelring in Gelbgold 585 mit ovaler Platte. Die Platte kann glatt bleiben oder eine Gravur aufnehmen — Motiv und Tiefe klären wir, bevor wir fertigen. Breite der Platte etwa acht Millimeter.', 'A signet ring in 585 yellow gold with an oval face. The face can stay plain or take an engraving — motif and depth are agreed before we make it. The face is about eight millimetres wide.', 'gold', 'Gelbgold', 'Yellow gold', '585 Gelbgold', '585 yellow gold', 8, 52, 70, 'Mit Gravur etwas länger. Den Termin nennen wir im Angebot.', 'A little longer with an engraving. We name the date in the offer.', 'signet', 'yellow', 10),
  ('trio', 'FJ-WR-002', 'weitere-ringe', 'Trio', 'Trio', 'Drei schmale Stapelringe in Rotgold 333, je 1,6 Millimeter. Sie werden als Satz angefragt und können einzeln nachbestellt werden. Die 333er-Legierung ist alltagstauglich und farblich kräftiger als feineres Gold.', 'Three narrow stacking rings in 333 red gold, 1.6 millimetres each. They are requested as a set and can be reordered one by one. The 333 alloy is made for daily wear and reads stronger in colour than finer gold.', 'gold', 'Rotgold', 'Red gold', '333 Rotgold', '333 red gold', 1.6, 48, 64, 'Den Termin nennen wir im Angebot, üblicherweise einige Wochen nach Freigabe.', 'We name the date in the offer, usually a few weeks after you approve it.', 'stack', 'red', 11),
  ('bogen', 'FJ-WR-003', 'weitere-ringe', 'Bogen', 'Bogen', 'Breites Silberband 925 mit leichter Außenwölbung, sechs Millimeter. Für den Alltag, nicht als Trauring gedacht. Silber läuft an — Pflege steht im Ratgeber.', 'A wide 925 silver band with a light outer curve, six millimetres. Made for everyday wear, not as a wedding ring. Silver tarnishes — care is in the guide.', 'silver', 'Silber', 'Silver', 'Silber 925', 'Silver 925', 6, 50, 70, 'Den Termin nennen wir im Angebot.', 'We name the date in the offer.', 'band', 'silver', 12),
  ('lina', 'FJ-KT-001', 'ketten', 'Lina', 'Lina', 'Ankerkette in Gelbgold 585. Glieder oval und flach, Standardlänge 45 Zentimeter, andere Längen auf Anfrage. Der Verschluss wird im Angebot genannt.', 'A trace chain in 585 yellow gold. Oval, flat links, standard length 45 centimetres, other lengths on request. The clasp is named in the offer.', 'gold', 'Gelbgold', 'Yellow gold', '585 Gelbgold', '585 yellow gold', null, null, null, 'Den Termin nennen wir im Angebot.', 'We name the date in the offer.', 'chain', 'yellow', 13),
  ('nera', 'FJ-KT-002', 'ketten', 'Nera', 'Nera', 'Kugelkette in Silber 925, Kugeln gleichmäßig, Länge 42 oder 50 Zentimeter. Leicht, für Anhänger mit kleiner Öse.', 'A bead chain in 925 silver, even beads, length 42 or 50 centimetres. Light, for a pendant with a small bail.', 'silver', 'Silber', 'Silver', 'Silber 925', 'Silver 925', null, null, null, 'Den Termin nennen wir im Angebot.', 'We name the date in the offer.', 'chain', 'silver', 14),
  ('ronda', 'FJ-OR-001', 'ohrringe', 'Ronda', 'Ronda', 'Creolen in Weißgold 585, Durchmesser etwa 16 Millimeter, runder Draht. Scharnier und Verschluss beschreiben wir im Angebot. Als Paar angefragt.', 'Hoops in 585 white gold, about 16 millimetres across, round wire. Hinge and catch are described in the offer. Requested as a pair.', 'gold', 'Weißgold', 'White gold', '585 Weißgold', '585 white gold', null, null, null, 'Den Termin nennen wir im Angebot.', 'We name the date in the offer.', 'hoop', 'white', 15),
  ('luz', 'FJ-OR-002', 'ohrringe', 'Luz', 'Luz', 'Ohrstecker in Roségold 750 mit einer kleinen gefassten Fläche. Stein oder glatte Kalotte — beides ist eine Anfrage, kein fertiges Lagerstück.', 'Studs in 750 rose gold with a small set face. A stone or a plain dome — either is a request, not a shelf piece.', 'gold', 'Roségold', 'Rose gold', '750 Roségold', '750 rose gold', null, null, null, 'Den Termin nennen wir im Angebot.', 'We name the date in the offer.', 'stud', 'rose', 16),
  ('tropfen', 'FJ-AH-001', 'anhaenger', 'Tropfen', 'Tropfen', 'Schlichter Tropfenanhänger in Gelbgold 750, hochglanz oder seidenmatt. Die Öse passt auf feine Ketten bis etwa 1,5 Millimeter.', 'A plain drop pendant in 750 yellow gold, polished or silk-matte. The bail fits fine chains up to about 1.5 millimetres.', 'gold', 'Gelbgold', 'Yellow gold', '750 Gelbgold', '750 yellow gold', null, null, null, 'Den Termin nennen wir im Angebot.', 'We name the date in the offer.', 'drop', 'yellow', 17),
  ('kreis', 'FJ-AH-002', 'anhaenger', 'Kreis', 'Kreis', 'Rundes Medaillon in Silber 925. Es öffnet sich nicht — die Fläche ist für eine Gravur oder bleibt leer. Durchmesser etwa 18 Millimeter.', 'A round locket-shaped pendant in 925 silver. It does not open — the face is for an engraving or stays empty. About 18 millimetres across.', 'silver', 'Silber', 'Silver', 'Silber 925', 'Silver 925', null, null, null, 'Den Termin nennen wir im Angebot.', 'We name the date in the offer.', 'locket', 'silver', 18)
insert into jewelry_profiles (code, name_de, name_en, description_de, description_en, svg_path, min_width_mm, max_width_mm, min_height_mm, max_height_mm, area_factor, allows_groove, allows_stones, sort_order) values
  ('planlinie', 'Planlinie', 'Flat line', 'Gerade Außen- und Innenfläche. Ruhig, gut für Gravur.', 'Straight outer and inner faces. Quiet, and good for engraving.', 'M22 18 H78 V46 H22 Z', 2, 8, 1.2, 2.4, 1, true, true, 1),
  ('hofband', 'Hofband', 'Court', 'Leicht gewölbte Außenseite, klassische Trauringlinie.', 'A lightly domed outside, the classic wedding-band line.', 'M22 46 H78 V30 Q50 14 22 30 Z', 2, 8, 1.3, 2.5, 0.86, true, true, 2),
  ('woelbling', 'Wölbling', 'High dome', 'Deutlich gewölbte Außenseite, mehr Licht auf der Mitte.', 'A clearly domed outside, with more light on the centre.', 'M20 48 H80 V34 Q50 6 20 34 Z', 2.2, 8, 1.4, 2.8, 0.78, true, true, 3),
  ('innenbogen', 'Innenbogen', 'Inner curve', 'Ebene Außenseite, zur Fingerseite hin gewölbt.', 'A flat outside, curved toward the finger.', 'M22 16 H78 V30 Q50 52 22 30 Z', 2, 8, 1.3, 2.6, 0.82, true, true, 4),
  ('doppelbogen', 'Doppelbogen', 'Double curve', 'Außen und innen gewölbt, weicher in der Hand.', 'Curved outside and in, softer in the hand.', 'M22 40 Q50 54 78 40 V26 Q50 8 22 26 Z', 2.2, 8, 1.4, 2.6, 0.75, true, true, 5),
  ('komfort', 'Komfort', 'Comfort', 'Runder Querschnitt. Liegt breit auf und drückt weniger.', 'A round section. It sits wide and presses less.', 'M32 32 Q32 14 50 14 Q68 14 68 32 Q68 50 50 50 Q32 50 32 32 Z', 2.2, 6, 1.6, 2.8, 0.72, false, true, 6),
  ('halbmond', 'Halbmond', 'Half moon', 'Halbrunde Außenseite, flache Innenseite.', 'A half-round outside and a flat inside.', 'M18 48 H82 Q50 8 18 48 Z', 2, 7, 1.4, 2.8, 0.7, false, true, 7),
  ('innenrund', 'Innenrund', 'Inner round', 'Halbrund zur Fingerseite, außen eben.', 'Half-round toward the finger, flat outside.', 'M18 16 H82 Q50 56 18 16 Z', 2, 7, 1.4, 2.6, 0.78, true, true, 8),
  ('dachfirst', 'Dachfirst', 'Ridge', 'Läuft nach außen in eine Kante aus. Schmal im Licht.', 'Runs out to an edge. Narrow in the light.', 'M16 48 H84 L50 10 Z', 2.5, 6, 1.8, 3.2, 0.5, false, false, 9),
  ('facette', 'Facette', 'Facet', 'Abgeschrägte Kanten, die Fläche in der Mitte bleibt plan.', 'Bevelled edges, with a flat face in the middle.', 'M22 24 L34 14 H66 L78 24 V40 L66 50 H34 L22 40 Z', 2.4, 8, 1.3, 2.4, 0.9, true, true, 10),
  ('schraege', 'Schräge', 'Bias', 'Eine Seite höher als die andere. Wirkt schmaler, als sie misst.', 'One side higher than the other. It looks narrower than it measures.', 'M20 16 H82 L64 50 H20 Z', 2.2, 7, 1.4, 2.6, 0.72, true, true, 11),
  ('keilband', 'Keilband', 'Wedge', 'Zur Innenseite schmaler. Liegt tiefer am Finger.', 'Narrower toward the inside. Sits lower on the finger.', 'M24 16 H76 L60 50 H40 Z', 2.4, 6.5, 1.5, 2.8, 0.62, false, false, 12),
  ('weichkante', 'Weichkante', 'Soft edge', 'Rechteck mit gerundeten Ecken. Weniger scharf am Nachbarring.', 'A rectangle with rounded corners. Less sharp against a neighbouring ring.', 'M30 14 H70 Q80 14 80 24 V40 Q80 50 70 50 H30 Q20 50 20 40 V24 Q20 14 30 14 Z', 2, 8, 1.2, 2.4, 0.94, true, true, 13),
  ('bombe', 'Bombé', 'Bombé', 'Bauchige Außenseite mit flacherem Fuß. Viel Fläche für Licht.', 'A bellied outside with a flatter foot. Plenty of face for light.', 'M24 42 Q24 12 50 12 Q76 12 76 42 Q76 52 50 52 Q24 52 24 42 Z', 2.4, 8, 1.5, 2.8, 0.8, true, true, 14),
  ('konkav', 'Konkav', 'Concave', 'Leichte Mulde über die Außenfläche. Hält eine Mattierung länger sichtbar.', 'A shallow hollow across the outside. Keeps a matte finish visible longer.', 'M18 26 Q50 38 82 26 V50 H18 Z', 2.6, 8, 1.4, 2.4, 0.88, true, true, 15),
  ('dprofil', 'D-Profil', 'D section', 'Flache Innenseite, runde Außenseite wie ein liegendes D.', 'A flat inside and a round outside, like a D on its side.', 'M22 14 H62 Q86 32 62 50 H22 Z', 2, 7, 1.4, 2.6, 0.85, true, true, 16),
  ('messerkante', 'Messerkante', 'Knife edge', 'Spitzt nach außen zu. Zart im Profil, empfindlicher im Alltag.', 'Comes to an edge outside. Delicate in profile, more exposed in daily wear.', 'M18 34 L50 10 L82 34 L50 52 Z', 2, 4.5, 1.8, 3.2, 0.5, false, false, 17),
  ('stufe', 'Stufe', 'Step', 'Ein Absatz über die Breite. Gut, wenn zwei Legierungen später nebeneinander liegen sollen.', 'A shoulder across the width. Useful when two alloys will sit side by side later.', 'M16 28 H40 V16 H84 V50 H16 Z', 3, 8, 1.2, 2.2, 0.92, true, true, 18),
  ('rohr', 'Rohr', 'Tube', 'Rundes Hohlprofil. Für fertige Röhrenringe und als Rohling für Werkstätten.', 'A round hollow section. For finished tube rings and as a blank for workshops.', 'M50 14 a18 18 0 1 0 0.01 0 Z M50 26 a6 6 0 1 1 -0.01 0 Z', 1.6, 3.6, 1.2, 2.2, 0.55, false, false, 19)
