insert into jewelry_finishes (code, name_de, name_en, description_de, description_en, preview, sort_order) values
  ('poliert', 'Hochglanz', 'Polished', 'Spiegelnd. Zeigt Kratzer früher, lässt sich nachpolieren.', 'Mirror-like. Shows scratches sooner, and can be repolished.', 'polish', 1),
  ('seidenmatt', 'Seidenmatt', 'Silk matte', 'Weiches, gleichmäßiges Matt ohne sichtbare Strichrichtung.', 'A soft, even matte with no visible grain.', 'matte', 2),
  ('gebuerstet', 'Gebürstet', 'Brushed', 'Feine Längsstriche um den Ring.', 'Fine lines running around the ring.', 'brush', 3),
  ('gehaemmert', 'Gehämmert', 'Hammered', 'Kleine Facetten von Hand. Jedes Stück etwas anders.', 'Small facets by hand. Each piece a little different.', 'hammer', 4),
  ('eis', 'Eis', 'Ice', 'Kühles, feinkörniges Matt mit hellem Streulicht.', 'A cool, fine-grained matte that scatters light.', 'ice', 5),
  ('sandmatt', 'Sandmatt', 'Sand matte', 'Gleichmäßig gesandelt, matter als Seide.', 'Evenly sanded, duller than silk.', 'sand', 6)
